from lib import *
S = SS('f109')
R = J('f109'); rl = R['rs_len']; st = R['struct']
steps = [
    step(f"JWT 的结构:三段 base64url,用点号分隔。header 是 {{\"alg\":\"HS256\",\"typ\":\"JWT\"}},payload 是 {{\"sub\":\"1\",\"role\":\"user\",\"iat\":…,\"exp\":…}},signature 是 43 个字符(HMAC-SHA256 的 32 字节)。整个令牌 {st[0]} 个字符,不验证签名就能读出 payload(role = user)——JWT 是签名,不是加密。", t=tl(S(1)), done=lidx(S(1), 'header', 'payload', 'signature'), mark=lidx(S(1), '不验证签名'), kv=KV([['header / payload', '明文 JSON'], ['signature', '防篡改'], ['长度', f'{st[0]} 字符']], ['header / payload'])),
    step("验证:jwt.decode 必须传 algorithms,不传抛 DecodeError「It is required that you pass in a value for the \"algorithms\" argument」;密钥错 → InvalidSignatureError;exp 过去 10 秒 → ExpiredSignatureError,加 leeway=30 就通过;nbf 在未来 → ImmatureSignatureError;没有 exp 的令牌默认通过(exp 不是强制的),要加 options={\"require\": [\"exp\"]} 才会报 MissingRequiredClaimError;要求 aud 但令牌没有 → MissingRequiredClaimError。", t=tl(S(2)), done=lidx(S(2), 'algorithms=[', 'leeway', '没有 exp(默认不要求)'), mark=lidx(S(2), '不传 algorithms', '错误的密钥', 'exp 已过去', 'nbf', 'require', 'aud'), kv=KV([['algorithms', '必须显式指定'], ['exp', '默认不强制,要 require'], ['leeway', '容忍时钟偏差']], ['exp'])),
    step("经典攻击:把 header 的 alg 改成 none 的伪造令牌,在 algorithms=['HS256'] 的验证下抛 InvalidAlgorithmError「The specified alg value is not allowed」;改 payload 里的 role 为 admin 并沿用旧签名 → InvalidSignatureError。只有关掉 verify_signature(options={'verify_signature': False})才会接受伪造令牌——永远不要这样用。", t=tl(S(3)), mark=lidx(S(3), 'alg=none', '改 role'), done=lidx(S(3), 'verify_signature'), kv=KV([['alg=none', 'algorithms 白名单拒绝'], ['改 payload', '签名对不上']], ['alg=none'])),
    step(f"HS256 与 RS256:RS256 令牌 {rl[0]} 个字符(HS256 是 {rl[1]}),用公钥验证通过;算法混淆攻击(把公钥当 HS256 的密钥)在 PyJWT 里被挡住,抛 InvalidKeyError「The specified key is an asymmetric key or x509 certificate and should not be used as an HMAC secret」,即使验证方同时允许 RS256 与 HS256 也一样。对称密钥谁有谁就能签发;非对称只有私钥持有者能签发,验证方只需要公钥。", t=tl(S(4)), done=lidx(S(4), 'RS256 令牌长度', '公钥验证'), mark=lidx(S(4), '算法混淆', '同时允许'), kv=KV([['HS256', '签发与验证用同一个密钥'], ['RS256', '公钥验证,私钥签发,令牌更长'], ['算法混淆', 'PyJWT 拒绝']], ['RS256'])),
    step("放进 Flask:/login 密码错 → 401;正确则发 15 分钟有效的令牌(160 字符),带令牌访问 /me → 200 {role: user, sub: 1}。把数据库里的角色改成 banned 之后,旧令牌仍然报告 role = user——JWT 是自包含的,有效期内不会跟着数据库变化;要即时生效就得缩短有效期、另存黑名单,或每次回查数据库(这样就失去了无状态的好处)。", t=tl(S(5)), done=lidx(S(5), '登录', '用令牌访问'), mark=lidx(S(5), '错误密码', 'banned'), kv=KV([['令牌里的 role', '有效期内不随数据库变化'], ['对策', '短有效期 + refresh(见第 110 篇)']], ['令牌里的 role'])),
]
A = mkartf('f109', 109, 'Flask,JWT,PyJWT,登录认证,真实验证,动画演示',
    '用 PyJWT 实测 JWT 登录认证:三段结构与明文 payload、algorithms 必须显式指定、exp 默认不强制、leeway、alg=none 与篡改 role 的攻击被拒绝、HS256 与 RS256 的差别与算法混淆被挡住、令牌里的 role 在有效期内不随数据库变化。',
    'JWT 里到底有什么?验证要注意哪些参数?alg=none 攻击在现在的库里还有效吗?令牌发出去之后怎么收回权限?这篇用 PyJWT 把每一步都跑一遍。',
    [('明文', 'JWT 的 payload 不需要密钥就能读出'), ('InvalidAlgorithmError', 'alg=none 的伪造令牌在 algorithms 白名单下的结果'), ('role = user', '数据库里角色改成 banned 之后,旧令牌仍然报告的角色')],
    [('JWT 的结构', '<p>上一篇:<a href="flask-api-token-auth.html">API Token 认证</a>;下一篇:<a href="flask-refresh-token.html">Refresh Token</a>。</p>'), ('验证与 claims', None), ('经典攻击', None), ('HS256 与 RS256', '<p>RS256 的实验需要 cryptography 包(我先装上了 50.0.2,没装之前这一节无法运行)。</p>'), ('放进 Flask', None)],
    steps, [ENV_F + '。PyJWT 2.15.1、cryptography 50.0.2', '没有验证:ES256 与 EdDSA、JWK 与 kid 的密钥轮换、jwks_uri 的远程密钥获取、JWE(加密的令牌)、浏览器端存放 JWT 的风险、Flask-JWT-Extended 的封装行为'], 'JWT 登录认证')
